// Hand-authored categories the generated emoji set can't express (Windows'
// panel ships both tabs; parity here). Kept OUT of emojiData.js because that
// file is regenerated by tools/gen_emoji_data.py.
//
// Entries are plain text: the codepoint list `cp` is computed from the
// literal string at load time, and `txt: true` tells the popup to render the
// cell in text style (no colour-emoji font). Recents/favourites key on `cp`,
// exactly like real emoji.

const e = (s, n, k) => ({
    cp: [...s].map((c) => c.codePointAt(0).toString(16)).join('-'),
    n,
    k: Array.isArray(k) ? k.join(' ') : k,
    t: 0,
    txt: true,
});

